insert into public.interactive_assignment_templates(slug,day,title,target_slugs,is_lab) values ('day-13-foundation-net-force',13,'Day 13 · Foundation: F = ma in practice',array['u1.fma-solve-net-force'],false);
insert into public.daily_lesson_templates(key,foundation_slug,review_slug,foundation_questions,review_questions,quiz) values ('unit-1-day-13','day-13-foundation-net-force','day-13-fma-practice',array['f13-sum','f13-pull','f13-mass','f13-brake','f13-exit'],array['r2-1a','r2-1b','r2-1c','r2-2a','r2-2b','r2-2c','r2-3a','r2-3b','r2-4a','r2-4b','r2-5a','r2-5b'],'{"title":"Day 13 · Quiz: Net force in practice","instructions":"Work on your own. Choose a positive direction and include units.","questions":[{"kind":"choice","points":1,"prompt":"A 3 kg cart feels 15 N right and 6 N left. What is its acceleration?","options":["3 m/s² right","5 m/s² right","9 m/s² right","3 m/s² left"],"correct_index":0,"guide":"Net force is 9 N right. Divide by 3 kg.","demand":{"blooms":"Apply","dok":2,"evidence":"Adds forces before dividing by mass."}},{"kind":"choice","points":1,"prompt":"A cart moves left at constant velocity. What is its net force?","options":["Left","Zero","Right","Equal to its mass"],"correct_index":1,"guide":"Constant velocity means zero acceleration.","demand":{"blooms":"Understand","dok":1,"evidence":"Distinguishes motion from acceleration."}},{"kind":"written","points":3,"prompt":"A 5 kg box accelerates right at 2 m/s². Friction acts left with 4 N. A classmate says the pull is 10 N right. Check their reasoning and find the pull.","guide":"10 N is the net force. The pull must be 14 N right so 14 − 4 = 10 N.","demand":{"blooms":"Analyze","dok":2,"evidence":"Distinguishes net and applied forces."}},{"kind":"written","points":3,"prompt":"A 1,000 kg car slows from +12 m/s to +4 m/s in 4 s at constant acceleration. Find its net force and explain how it can still move forward.","guide":"Acceleration is −2 m/s² and the net force is −2,000 N. Velocity stays positive as it gets smaller.","demand":{"blooms":"Analyze","dok":2,"evidence":"Connects a signed change in velocity to a braking force."}}]}'::jsonb);
